const crypto = require('crypto');
const secret = 'test-webhook-secret-123';
const headers = $json.headers || {};
const signature = headers['x-n8n-signature'];
const raw = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body || {});
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (expected !== signature) throw new Error('Invalid signature');
const payload = JSON.parse(raw);
return [{ json: { request_id: payload.request_id, brand_id: payload.brand_id, brief: payload.brief, started_at: new Date().toISOString() } }];

const brand = $json;
const completeness = brand.completeness_score || 0;
let mode = 'Standard';
if (completeness < 0.3) mode = 'Blocked';
else if (completeness < 0.75) mode = 'Cautious';
const watermark = (mode !== 'Standard');
return [{ json: { brand, confidenceMode: mode, forceWatermark: watermark } }];

const crypto = require('crypto');
const trigger = $("Verify HMAC + parse").first().json;
const brand = $("Initial confidence gate").first().json.brand;

const payload = {
  flow_id: 'N8N-A02',
  brand_id: trigger.brand_id,
  payload: {
    request_type: 'calendar_ondemand',
    trigger_payload: {
      request_id:   trigger.request_id,
      objective:    trigger.brief.objective,
      content_type: trigger.brief.content_type,
      media_type:   trigger.brief.media_type || 'image',
      user_prompt:  trigger.brief.hero_concept || null,
    },
    occasion_flags: trigger.brief.occasion_name ? [trigger.brief.occasion_name] : [],
  },
};

const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/ceo/classify', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() } } }];

const decision = $json.result?.decision || $json;
const trigger = $('Verify HMAC + parse').first().json;
return [{ json: { decision, trigger, requires_ref_img: decision.requires_ref_img || false } }];

const crypto = require('crypto');
const ctx = $json;
const trigger = ctx.trigger;
const brand = ctx.brand;
const objectiveMix = {
  educational: { educational: 0.5, experiential: 0.3, promotional: 0.2 },
  promotional: { educational: 0.2, experiential: 0.3, promotional: 0.5 },
  experiential: { educational: 0.3, experiential: 0.5, promotional: 0.2 }
};
const contentMix = objectiveMix[trigger.brief.content_type] || { educational: 0.3, experiential: 0.4, promotional: 0.3 };
const payload = {
  flow_id: 'N8N-A02',
  brand_id: trigger.brand_id,
  payload: {
    confidence_mode: ctx.confidenceMode,
    request_type: 'calendar_ondemand',
    occasion_flags: trigger.brief.occasion_name ? [trigger.brief.occasion_name] : [],
    platform_spec: brand.primary_channel || 'Instagram',
    content_mix: contentMix,
    post_count: 1,
    brand: {
      brand_id: brand.brand_id,
      sector: brand.sector,
      dialect: brand.arabic_dialect,
      brand_name_ar: brand.brand_name_ar,
      primary_color_hex: brand.primary_color_hex
    },
    reference_image_url: ctx.reference_image_url
  }
};
const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/coo/compile-caption-context', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() } } }];

const trigger = $('Verify HMAC + parse').first().json;
// Carry request_id inside flags so the admin QA classifier tags this hold as
// on_demand (packages/db/src/queries/admin.ts: classifyQa keys on flags.request_id).
// Without it the dialect hold has no post_id and no flags.request_id, so it
// silently defaulted into the Calendar QA tab.
const flags = { reason: 'dialect_unconfirmed', request_id: trigger.request_id };
return [{ json: { request_id: trigger.request_id, brand_id: trigger.brand_id, status: 'pending', failure_reason: 'dialect_unconfirmed', flags } }];

const crypto = require('crypto');
const trigger = $('Verify HMAC + parse').first().json;
const watermark = $('Initial confidence gate').first().json.forceWatermark;

// Explicitly read the COO HTTP response — $json here is the Supabase Step:coo
// output (a DB row), not the COO API result, so we must reference it by name.
const cooResp = $('POST /api/agents/coo/compile-caption-context').first().json;
const cooResult = cooResp.result || cooResp;
const captionContext = cooResult.caption_context || null;

if (!captionContext) throw new Error('COO caption_context missing — cannot call DeepSeek');

// Build schedule_dates from the on-demand posting_time.
// The DeepSeek prompt contract: post_count MUST equal schedule_dates.length and
// the model must never invent its own dates. Sending schedule_dates=[] with
// post_count=1 causes DeepSeek to return posts=[] (triggering the 502 guard).
const rawPostingTime = trigger.brief.posting_time || new Date().toISOString();
const scheduleDate = rawPostingTime.slice(0, 10);
const hourMatch = rawPostingTime.match(/T(\d{2}):/);
const scheduleHour = hourMatch ? parseInt(hourMatch[1], 10) : 12;
const schedule_dates = [{ date: scheduleDate, posting_time: rawPostingTime, hour: scheduleHour }];

const payload = { flow_id: 'N8N-A02', brand_id: trigger.brand_id, payload: { month: trigger.brief.month, caption_context: captionContext, post_count: 1, schedule_dates, start_date: scheduleDate, occasion_context: trigger.brief.occasion_name ? { name: trigger.brief.occasion_name } : undefined, watermark_required: watermark } };
const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/deepseek/generate', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() } } }];

const crypto = require('crypto');
const trigger = $('Verify HMAC + parse').first().json;

// $json here is Step:caption (Supabase UPDATE) — must reference DeepSeek directly.
const dsResp = $('POST /api/agents/deepseek/generate').first().json;
const ds = dsResp.result || dsResp;
const caption = (ds.captions || ds.posts || [])[0];

if (!caption) throw new Error('DeepSeek returned no captions — cannot run CCO QC');

const cooResponse = $('POST /api/agents/coo/compile-caption-context').first().json;
const captionContext = cooResponse.result?.caption_context || cooResponse.caption_context || '';
const captionContextExcerpt = captionContext.slice(0, 500) || 'context unavailable';

const payload = {
  flow_id: 'N8N-A02',
  brand_id: trigger.brand_id,
  payload: {
    caption_context_excerpt: captionContextExcerpt,
    posts: [{
      post_id: crypto.randomUUID(),
      caption_ar: caption.caption_ar,
      content_type: trigger.brief.content_type
    }]
  }
};
const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/cco/qc', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() }, __caption: caption } }];

const crypto = require('crypto');
const trigger = $("Verify HMAC + parse").first().json;

// $json here is Step:qc (a Supabase UPDATE row), NOT the CCO response — read the
// CCO HTTP response by node name. cco/qc returns `result` as an ARRAY of
// evaluations (older builds nested it under .evaluations) — parse both shapes.
// FIX: the old code read cco.evaluations[0] off the wrong object, so the CEO
// confidence gate ALWAYS received a fabricated score of 85. Also `score || 85`
// destroyed real hard-block zeros (0 is falsy) — typeof check preserves them.
const ccoResp = $("POST /api/agents/cco/qc").first().json;
const ccoArr = Array.isArray(ccoResp.result) ? ccoResp.result
  : (Array.isArray(ccoResp.evaluations) ? ccoResp.evaluations
  : (ccoResp.result?.evaluations || ccoResp.evaluations || []));
const eval0 = ccoArr[0] || {};
const braveRouteFlag = eval0.brave_route_flag || false;
const negpatFlag     = eval0.negpat_flag || 'NONE';
const ccoScore       = (typeof eval0.score === 'number') ? eval0.score : 85;

const ceoStep1    = $("Log routing_decision (CEO1)").first().json.decision || {};
const selectedChain = ceoStep1.selected_chain || null;
const chainContext  = ceoStep1.chain_context  || null;

const payload = {
  flow_id:  'N8N-A02',
  brand_id: trigger.brand_id,
  payload: {
    request_type:   'calendar_ondemand',
    trigger_payload: { request_id: trigger.request_id },
    cco_results: [{
      post_id:          crypto.randomUUID(),
      score:            ccoScore,
      brave_route_flag: braveRouteFlag,
      negpat_flag:      negpatFlag,
    }],
    selected_chain: selectedChain,
    chain_context:  chainContext,
  },
};

const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/ceo/confidence-gate', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() }, __caption: $("Prepare CCO").first().json.__caption } }];

const gate = ($json.result?.decision && typeof $json.result.decision === 'object') ? $json.result.decision : ($json.decision || {});
const trigger = $('Verify HMAC + parse').first().json;
const forceWatermark = $('Initial confidence gate').first().json.forceWatermark;
let route = 'clean';
if (gate.human_gate_required) route = 'hold';
else if (forceWatermark || gate.confidence_mode === 'Cautious' || gate.confidence_mode === 'Minimal') route = 'watermark';
return [{ json: { route, __caption: $('Prepare CEO confidence gate').first().json.__caption, gate, trigger } }];

// Build the qa_review_queue hold row AFTER the post exists, so post_id links the
// already-generated media into admin QA (Generate-Then-Review).
const cal = $('Prepare calendar row').first().json;
const insertedPost = $('Insert calendar_posts').first().json;
return [{ json: {
  brand_id: cal.brand_id,
  caption_ar: cal.caption_ar,
  cco_score: cal.cco_score,
  flags: cal.flags,
  trigger_reason: cal.trigger_reason,
  status: 'pending',
  post_id: insertedPost.post_id || null,
} }];

const crypto = require('crypto');
const d = $json;
const ctx = $('Merge context').first().json;
const brand = ctx.brand;
const trigger = ctx.trigger;

let chainId = null;
let productDescriptor = null;
try {
  const ceoDecision = $('Log routing_decision (CEO1)').first().json.decision;
  chainId = (ceoDecision && ceoDecision.selected_chain) || null;
  productDescriptor = (ceoDecision && ceoDecision.chain_context && ceoDecision.chain_context.product_descriptor) || null;
} catch (e) {
  chainId = null;
}

// FIX: On-demand mode — user's explicit prompt ALWAYS takes precedence (Hard Rule #1: CEO routes)
// On-demand users supply their own prompt — NEVER use chain descriptors or DeepSeek auto-brief
// Priority: User's hero_concept/style_descriptor > NOTHING ELSE in on-demand mode
const rawPrompt = ((trigger.brief.hero_concept || '') + ' ' + (trigger.brief.style_descriptor || '')).trim();
const visualBriefEn = (d.__caption && d.__caption.visual_brief_en) || null;

const weavyContext = {
  brand_id: trigger.brand_id,
  post_id: crypto.randomUUID(),
  prompt_en: rawPrompt || visualBriefEn,  // IGNORE productDescriptor entirely in on-demand mode
  brand_name_ar: brand.brand_name_ar,
  headline_ar: (d.__caption && d.__caption.caption_ar ? d.__caption.caption_ar : '').slice(0, 50),
  dialect: brand.arabic_dialect,
  channel: trigger.brief.platform || 'Instagram',
  objective: trigger.brief.objective,
  confidence_flag: (d.route === 'watermark' || d.route === 'hold') ? 'watermark_required' : 'clean',
  reference_image_url: ctx.reference_image_url,
  expected_media_type: (trigger.brief && trigger.brief.media_type) || 'image',
  chain_id: chainId,
  chain_context: undefined,  // CRITICAL: on-demand MUST NOT send chain_context — N8N-V01 uses product_descriptor over prompt_en
  // sharp_text_gravity: provide explicit null so N8N-V01 layout lookup is defined.
  // TODO: derive from CEO visual zone recommendation once available.
  sharp_text_gravity: (d.__caption && d.__caption.text_gravity) || null
};
return [{ json: { ...weavyContext, __caption: d.__caption, trigger, route: d.route } }];

// Step: image (Supabase UPDATE) returns the on_demand_requests row,
// which has no brand_name_ar / dialect / headline_ar / prompt_en.
// This node restores the weavyContext that Prepare V01 call built so
// Execute N8N-V01 sub-workflow receives the correct overlay fields.
return [{ json: $('Prepare V01 call').first().json }];

const crypto = require('crypto');
const v01result = $json;
const storage_url = v01result.storage_url;
const clean_storage_url = v01result.clean_storage_url || null;
const keyframe_url = v01result.keyframe_url || null;
const trigger = $('Prepare V01 call').first().json.trigger;

// For async video, storage_url is null at this point (fal job is queued, not yet
// rendered). DO NOT throw — QC runs on the KEYFRAME instead (see below).
const isVideo = !!(trigger.brief && trigger.brief.media_type === 'video');
if (!isVideo && !storage_url) throw new Error('Image generation failed (V01): ' + (v01result.error || v01result.message || 'no storage_url returned'));

// VIDEO BRAND QC: the keyframe IS the first frame the animator (Kling) animates —
// an off-brand keyframe means an off-brand video. Run cco/visual-qc on it so video
// gets the SAME brand_relevance + cultural gate as images. __video_qc_real tells
// 'Prepare calendar row' the verdict is meaningful; only when NO keyframe exists
// do we fall back to the placeholder + forced pass (fail-open, never blocks).
const videoQcReal = isVideo && !!keyframe_url;
const qcImageUrl = isVideo
  ? (keyframe_url || 'https://app.openclaw.com/assets/visual-placeholder.png')
  : storage_url;

const payload = { flow_id: 'N8N-A02', brand_id: trigger.brand_id, payload: { image_url: qcImageUrl } };
const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/cco/visual-qc', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() }, __storage_url: storage_url, __clean_storage_url: clean_storage_url || (isVideo ? keyframe_url : null), __video_qc_real: videoQcReal, __caption: $('Prepare V01 call').first().json.__caption, __trigger: trigger, __route: $('Prepare V01 call').first().json.route, __image_prompt_en: (v01result.image_prompt_en || null) } }];

// Generate-Then-Review: always insert the generated post. Decide moderation here.
const prep = $('Prepare visual QC').first().json;
const vqcResp = $('POST /api/agents/cco/visual-qc').first().json;
const isVideo = !!(prep.__trigger.brief && prep.__trigger.brief.media_type === 'video');
const PASS_THRESHOLD = 70; // keep in lockstep with apps/web/src/app/api/agents/cco/visual-qc/route.ts (PASS_THRESHOLD)
const vqcPass = vqcResp.result?.pass ?? vqcResp.pass;
// VIDEO BRAND QC: when the KEYFRAME was QC'd (__video_qc_real), the verdict is real —
// the animator renders that exact frame, so an off-brand keyframe = off-brand video.
// Only when no keyframe exists (legacy/error path) does video fall back to forced pass.
const videoQcReal = prep.__video_qc_real === true;
const videoBypass = isVideo && !videoQcReal;
const vqcScore = videoBypass ? 100 : (vqcResp.result?.score ?? vqcResp.score ?? null);
// Trust the API's authoritative pass flag (score >= 70 AND no hard-block violations
// AND on-brand). cco/visual-qc scores brand_relevance, so an OFF-BRAND image OR video
// keyframe returns pass:false and is held here for admin review.
const visualPass = videoBypass ? true : (typeof vqcPass === 'boolean' ? vqcPass : (vqcScore != null && vqcScore >= PASS_THRESHOLD));
// off_brand flag set by cco/visual-qc when brand_relevance < threshold (image unrelated to brand).
const offBrand = (vqcResp.result?.off_brand ?? vqcResp.off_brand) === true;
const route = prep.__route;

// CCO Arabic QC returns an ARRAY of evaluations ({ ok, result: [ {score, negpat_flag,...} ] }).
// FIX: read result[0] (NOT result.evaluations[0], which made cco_score always 0). A missing
// score is null (unknown) and never forces a hold. cco_score is metadata only — brand relevance
// is judged on the IMAGE in cco/visual-qc, so we do NOT gate on the caption-level cco_score.
const ccoResp = $('POST /api/agents/cco/qc').first().json;
const ccoArr = Array.isArray(ccoResp.result) ? ccoResp.result
  : (Array.isArray(ccoResp.evaluations) ? ccoResp.evaluations
  : (ccoResp.result?.evaluations || ccoResp.evaluations || []));
const ccoEval = ccoArr[0] || {};
const cco_score = (typeof ccoEval.score === 'number') ? ccoEval.score : null;
const gate = ($('Derive route').first().json.gate) || {};

// HOLD POLICY (generate-then-review): hold for admin review when visual QC fails (this now
// includes OFF-BRAND images), or when the CEO raised a non-maturity human-gate. A purely
// brand-maturity soft gate (e.g. first_ever_client_output) still auto-delivers.
const ceoHumanGate = !!(gate && gate.human_gate_required === true);
const SOFT_IGNORE = new Set(['first_ever_client_output','brand_maturity_low']);
const gateReasons = (gate.human_gate_reasons || []).filter(Boolean);
const onlySoftMaturity = gateReasons.length > 0 && gateReasons.every(function (r) { return SOFT_IGNORE.has(r); });

// IMAGE VERIFICATION GATE (cco/image-verify): second vision gate scoring how well
// the generated asset matches the user's request (prompt_adherence) + the brand
// guidelines (brand_consistency). FAIL-OPEN: a missing / errored / vision_failed
// response NEVER holds — the gate adds protection, never new failure modes.
let verifyResp = {};
try { verifyResp = $('POST /api/agents/cco/image-verify').first().json || {}; } catch (e) { verifyResp = {}; }
const verify = verifyResp.result || verifyResp || {};
const verifyRan = (typeof verify.pass === 'boolean') && verify.vision_failed !== true;
const verifyPass = verifyRan ? verify.pass : true;

const needs_review = (!visualPass) || (!verifyPass) || (ceoHumanGate && !onlySoftMaturity);

let trigger_reason;
if (!visualPass) {
  trigger_reason = offBrand ? 'off_brand' : 'visual_qc_failed';
} else if (!verifyPass) {
  trigger_reason = (verify.brand_consistency != null && verify.brand_consistency < 60) ? 'brand_mismatch' : 'prompt_mismatch';
} else {
  trigger_reason = gateReasons.length > 0 ? gateReasons.join('|') : 'ceo_hold';
}
const flags = {
  reason: !visualPass ? (offBrand ? 'off_brand' : 'visual_qc_failed') : (!verifyPass ? trigger_reason : 'human_gate'),
  request_id: prep.__trigger.request_id,
  negpat_flag: ccoEval.negpat_flag || 'NONE',
  brave_route_flag: ccoEval.brave_route_flag || false,
  brand_relevance: (vqcResp.result?.brand_relevance ?? vqcResp.brand_relevance ?? null),
  cco_score: cco_score,
  // Image-verify evaluation details — shown in admin QA (flags JSONB passthrough).
  prompt_adherence: (verify.prompt_adherence != null ? verify.prompt_adherence : null),
  brand_consistency: (verify.brand_consistency != null ? verify.brand_consistency : null),
  verify_missing: (verify.missing_elements || []).slice(0, 10),
  verify_mismatches: (verify.mismatches || []).slice(0, 10),
  verify_reasoning: (((verify.reasoning || '') + '').slice(0, 500)) || null,
};
// ACCURATE SCORING: when the vision model failed (safe-pass path returns a
// fabricated 85/90), store NULL so the admin UI shows '—' instead of a fake
// number. A real score is stored as-is; there is no invented fallback anymore.
const vqcFailed = ((vqcResp.result?.vision_failed ?? vqcResp.vision_failed) === true);
const confidence_score = vqcFailed ? null
  : (vqcResp.result?.score != null) ? vqcResp.result.score
  : (vqcResp.score != null ? vqcResp.score : null);

// CHAIN TRACEABILITY: the selected chain + product descriptor were resolved by the CEO and
// passed to N8N-V01 via "Prepare V01 call" (weavyContext.chain_id, e.g. "U05"). Persist them
// to calendar_posts so the admin QA UI can show which chain generated the asset.
// generation_model is best-effort: use V01's resolved model when it echoes one, otherwise
// leave null and let the admin UI derive it from the chain (chains.fal_model_primary).
const v01ctx = $('Prepare V01 call').first().json || {};
const chain_id = v01ctx.chain_id || null;
let generation_model = null;
try {
  const v01out = $('Restore V01 input').first().json || {};
  generation_model = v01out.generation_model || v01out.model || v01out.fal_model || v01ctx.generation_model || null;
} catch (e) { generation_model = null; }

return [{ json: {
  brand_id: prep.__trigger.brand_id,
  caption_ar: prep.__caption.caption_ar,
  storage_url: prep.__storage_url,
  clean_storage_url: prep.__clean_storage_url || null,
  confidence_score,
  watermark: route === 'watermark' || route === 'hold' || needs_review,
  // pending_review = generated but awaiting admin moderation; otherwise draft.
  status: needs_review ? 'pending_review' : 'draft',
  media_type: (prep.__trigger.brief && prep.__trigger.brief.media_type) || 'image',
  on_demand_request_id: prep.__trigger.request_id,
  // Chain provenance persisted to calendar_posts (read by admin QA UI).
  chain_id,
  generation_model,
  // Final English prompt actually sent to fal.ai (admin QA visibility).
  image_prompt_en: prep.__image_prompt_en || null,
  // passthrough (not inserted) — read by "Prepare hold record" / "Needs review?"
  needs_review, trigger_reason, flags, cco_score, request_id: prep.__trigger.request_id,
} }];

const trigger = $('Prepare V01 call').first().json.trigger;
const insertedPost = $('Insert calendar_posts').first().json;
// BUG FIX 5: For video, the fal.ai animation job is still queued — the video has NOT rendered
// yet. Set status='generating' so the UI shows a progress placeholder. The video-callback
// route (/api/webhooks/fal-ai/video-callback) will set status='delivered' when the MP4 is
// uploaded to Supabase Storage (2-5 min later). For images the asset is already in Storage,
// so 'delivered' is correct immediately.
const isVideo = !!(trigger.brief && trigger.brief.media_type === 'video');
return [{ json: { request_id: trigger.request_id, status: isVideo ? 'generating' : 'delivered', delivered_at: isVideo ? null : new Date().toISOString(), post_id: insertedPost.post_id || null } }];

const crypto = require('crypto');
const trigger = $('Verify HMAC + parse').first().json;
const status = ($json.status || '').toString().trim();
const failureReason = ($json.failure_reason || '').toString().trim();
const nominations = (status === 'failed' && failureReason === 'visual_qc_failed')
  ? [{ nomination_type: 'negative_pattern_add', nomination_data: { pattern: 'visual_qc_failed' } }]
  : [];
const payload = { flow_id: 'N8N-A02', brand_id: trigger.brand_id, payload: { nominations } };
const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
return [{ json: { url: 'https://petition-cupid-buffed.ngrok-free.dev/api/agents/ceo/nominate', body: raw, headers: { 'x-n8n-signature': sig, 'x-n8n-request-id': crypto.randomUUID(), 'x-n8n-timestamp': new Date().toISOString() } } }];

const crypto = require('crypto');
const trigger = $('Verify HMAC + parse').first().json;
const payload = { event_type: 'on_demand_complete', flow_id: 'N8N-A02', brand_id: trigger.brand_id, payload: { request_id: trigger.request_id } };
const raw = JSON.stringify(payload);
const sig = crypto.createHmac('sha256', (function(){try{return $env.N8N_WEBHOOK_SECRET||null}catch(_){return null}})()||'test-webhook-secret-123').update(raw).digest('hex');
