}}];

// HMAC-signed S03 anomaly alert built from Catch Error output.
// request_id is always available here — Catch Error reads it from Verify HMAC + parse
// within the same execution.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';

const request_id    = $json._request_id    ?? null;
const brand_id      = $json._brand_id      ?? null;
const error_message = $json._error_message ?? 'A02 on-demand flow failed';
const failed_node   = $json._failed_node   ?? null;

const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'n8n_failure',
  severity:     'error',
  source_flow:  'N8N-A02',
  brand_id,
  message:      error_message,
  details:      { failed_node, request_id },
  timestamp:    new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return [{ json: {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-a02`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
  _request_id:     request_id,
  _failure_reason: error_message,
}}];

const request_id = $json._request_id;
if (!request_id) return [];
const msg = (() => { try { return JSON.parse($json._body).message; } catch(_) { return 'workflow_error'; } })();
return [{ json: { request_id, failure_reason: String(msg).slice(0, 500) } }];

